import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { FaUserPlus, FaHospital, FaMoneyBillWave, FaPills } from 'react-icons/fa';
import StatsCard from '../../components/Common/StatsCard';
import RevenueChart from '../../components/Common/RevenueChart';

const ReceptionistDashboard = () => {
  const [stats, setStats] = useState({
    todayPatients: 0,
    currentAdmissions: 0,
    todayRevenue: 0,
    lowStockMedicines: [],
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      const response = await axios.get('/api/dashboard/receptionist');
      setStats(response.data);
    } catch (error) {
      console.error('Error fetching dashboard:', error);
    } finally {
      setLoading(false);
    }
  };

  const statCards = [
    { title: "Today's Patients", value: stats.todayPatients, icon: FaUserPlus, color: 'blue' },
    { title: 'Current Admissions', value: stats.currentAdmissions, icon: FaHospital, color: 'green' },
    { title: "Today's Revenue", value: `KSh ${stats.todayRevenue}`, icon: FaMoneyBillWave, color: 'yellow' },
    { title: 'Low Stock Items', value: stats.lowStockMedicines?.length || 0, icon: FaPills, color: 'red' },
  ];

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="w-16 h-16 border-4 border-primary-600 border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-gray-900">Receptionist Dashboard</h1>
        <p className="text-gray-500">Welcome back! Here's your daily overview.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {statCards.map((stat) => (
          <StatsCard key={stat.title} {...stat} />
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="card p-6">
          <h2 className="text-lg font-semibold text-gray-900 mb-4">Revenue Overview</h2>
          <RevenueChart />
        </div>
        <div className="card p-6">
          <h2 className="text-lg font-semibold text-gray-900 mb-4">Low Stock Medicines</h2>
          {stats.lowStockMedicines?.length > 0 ? (
            <div className="space-y-2">
              {stats.lowStockMedicines.slice(0, 5).map((med) => (
                <div key={med.id} className="flex justify-between items-center p-2 bg-red-50 rounded">
                  <span className="font-medium text-gray-700">{med.name}</span>
                  <span className="text-sm text-red-600 font-semibold">
                    Stock: {med.currentStock}
                  </span>
                </div>
              ))}
            </div>
          ) : (
            <p className="text-gray-500 text-sm">All medicines are well stocked ✅</p>
          )}
        </div>
      </div>
    </div>
  );
};

export default ReceptionistDashboard;
